import{_ as s,a as o}from"./chunks/page-management.C1N4HV8y.js";import{_ as i,m as n,k as l,q as e,ah as r,B as t}from"./chunks/framework.HEc25T99.js";const P=JSON.parse('{"title":"Pages","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"developers/admin-panel/content-management/pages.md","filePath":"src/en/developers/admin-panel/content-management/pages.md"}'),c={name:"developers/admin-panel/content-management/pages.md"},d=s+"#light-only",p=o+"#dark-only";function g(h,a,m,u,f,_){return l(),n("div",null,[...a[0]||(a[0]=[e("h1",{id:"pages",tabindex:"-1"},[t("Pages "),e("a",{class:"header-anchor",href:"#pages","aria-label":'Permalink to "Pages"'},"​")],-1),e("p",null,[t("This section (labeled "),e("strong",null,"Page Sections"),t(" in the side menu) manages the site's pages and the assembly of their sections. It corresponds to the "),e("a",{href:"./../../resources/cli.html#creopse-page-alias-pag"},[e("code",null,"creopse page")]),t(" CLI group.")],-1),e("p",null,[e("img",{src:d,alt:"Pages"}),e("img",{src:p,alt:"Pages"})],-1),r('<h2 id="page-list" tabindex="-1">Page list <a class="header-anchor" href="#page-list" aria-label="Permalink to &quot;Page list&quot;">​</a></h2><p>A <strong>Filter pages</strong> field lets you search for a page by name. At the bottom of the list:</p><ul><li><strong>Add page</strong> — creates a new page (title per language, display position).</li><li><strong>Rearrange pages</strong> — changes the order of pages in the list (does not affect their URL).</li></ul><h2 id="page-detail" tabindex="-1">Page detail <a class="header-anchor" href="#page-detail" aria-label="Permalink to &quot;Page detail&quot;">​</a></h2><p>Once a page is selected from the list:</p><ul><li><strong>Edit page</strong> — edits the title (per language), content and position of the page.</li><li><strong>Delete</strong> — removes the page.</li><li><strong>Open the visual editor</strong> — switches to the <a href="./visual-editor.html">visual editor</a> for this page.</li></ul><h3 id="attached-sections" tabindex="-1">Attached sections <a class="header-anchor" href="#attached-sections" aria-label="Permalink to &quot;Attached sections&quot;">​</a></h3><p>Each section attached to the page appears in an ordered list, with:</p><ul><li>a reorder handle (drag and drop);</li><li>a <strong>Display</strong> checkbox — enables/disables the instance without detaching it (equivalent to <code>creopse page toggle-section-status</code>);</li><li>the section&#39;s name;</li><li>a <strong>Data &amp; Settings</strong> button — edits the data and settings of this specific section instance;</li><li>a counter (&quot;X Section(s)&quot;) at the bottom of the list.</li></ul><p>The <strong>Insert or remove sections</strong> block lets you attach a new section instance to the page, or detach an existing one.</p><div class="tip custom-block"><p class="custom-block-title">For developers</p><p>Creating pages and attaching sections (with <code>link-id</code>, ordering, enabling/disabling) can also be scripted through the CLI — see <a href="./../../development/pages.html">Pages</a> and how sections work in detail in <a href="./../../development/sections-widgets.html">Sections &amp; Widgets</a>.</p></div><div class="tip custom-block"><p class="custom-block-title">See also</p><p>An end-user–oriented version of this section exists in the <a href="./../../../users/sections/content-management.html">User Guide</a>.</p></div>',12)])])}const k=i(c,[["render",g]]);export{P as __pageData,k as default};
